insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_151'
from (values
('127.922.d.3',3,'A ramp worker in a transportation practicum puts on a hi-vis vest, checks that her hearing protection fits and walks around the aircraft tug before starting it. She is:','["understanding and applying proper safety techniques in the workplace", "hurrying to finish", "avoiding her duties", "guessing at the rules"]'::jsonb,0,'Safety techniques.','original'),
('127.922.d.3',4,'Why do trained workers follow safety techniques even on routine jobs?','["Routine jobs are never dangerous", "Most accidents happen when routine steps are skipped", "Safety is only for new hires", "Supervisors enjoy extra paperwork"]'::jsonb,1,'Routine tasks still carry risk.','original'),
('127.922.d.1.A',3,'During a shift handoff, a dispatcher gives the next person a short, clear summary and points to the map to show the delay. She is:','["rambling without a point", "using unclear slang", "using verbal and non-verbal communication in a clear, concise and effective manner", "staying silent"]'::jsonb,2,'Clear communication.','original'),
('127.922.d.1.A',4,'Which message to a crew is the clearest and most concise?','["\"Um, you know, that truck thing, sometime later maybe.\"", "\"Go get stuff done soon.\"", "\"Somebody should probably do something at the docks.\"", "\"Truck 4 loads at Dock B by 2:00 p.m.\""]'::jsonb,3,'Specific details make it clear.','original'),
('127.922.d.1.B',3,'A trainee reads a fuel-use chart for three delivery routes, explains which route costs most and gives the numbers to her supervisor. She is:','["analyzing, interpreting and communicating data and observations effectively", "copying numbers blindly", "ignoring the routes", "hiding the chart"]'::jsonb,0,'Data communication.','original'),
('127.922.d.1.B',4,'When reporting data to a supervisor, a worker should:','["avoid mentioning the source", "state what the numbers show and what they mean", "list numbers with no explanation", "report only guesses"]'::jsonb,1,'Explain the meaning.','original'),
('127.922.d.1.C',3,'A trainee sees her supervisor''s furrowed brow while she explains a delay and slows down to ask if more detail would help. She is:','["talking faster", "ignoring the supervisor", "observing and interpreting nonverbal cues to improve communication", "leaving the room"]'::jsonb,2,'Nonverbal cues.','original'),
('127.922.d.1.C',4,'A customer says ''fine'' but crosses her arms and looks away. A skilled worker would:','["walk away", "assume everything is fine", "finish the paperwork quickly", "ask a follow-up question to find out what is wrong"]'::jsonb,3,'Words and body can differ.','original'),
('127.922.d.1.D',3,'A trainee repeats a pickup address back to the caller and asks, ''Is that the north entrance?'' before dispatching a driver. She is:','["applying active listening to obtain and clarify information", "skipping the check", "interrupting the caller", "assuming the address"]'::jsonb,0,'Clarify.','original'),
('127.922.d.1.D',4,'Which habit is part of active listening?','["Planning your answer while the speaker talks", "Asking questions to confirm what was said", "Looking at a phone", "Finishing the speaker''s sentences"]'::jsonb,1,'Active listening.','original'),
('127.922.d.2.A',3,'A trainee''s cart will not start, so she checks the battery, then the cable, then the switch, using each result to decide what to test next. She is:','["guessing randomly", "giving up at once", "employing critical-thinking skills independently with increased fluency", "changing everything at once"]'::jsonb,2,'Critical thinking.','original'),
('127.922.d.2.A',4,'Critical thinking at work means a person:','["follows the first idea", "avoids hard problems", "copies a coworker without checking", "weighs evidence before deciding"]'::jsonb,3,'Weigh evidence.','original'),
('127.922.d.2.B',3,'A warehouse crew keeps blocking an aisle, so a trainee proposes painting loading zones and changing the pickup order. She is:','["analyzing elements of a problem to develop creative and innovative solutions", "ignoring the aisle", "leaving the problem alone", "blaming the crew"]'::jsonb,0,'Innovative solutions.','original'),
('127.922.d.2.B',4,'Before offering a creative fix, a worker should first:','["wait for someone else", "identify the parts and the cause of the problem", "pick a favorite idea", "order new equipment"]'::jsonb,1,'Analyze first.','original'),
('127.922.d.2.C',3,'A trainee tells a customer that the part has a worn bearing and needs a torque check, using the terms her program taught. She is:','["avoiding terms", "speaking in slang only", "using content, technical concepts and vocabulary when analyzing information", "using made-up words"]'::jsonb,2,'Technical vocabulary.','original'),
('127.922.d.2.C',4,'Why is accurate technical vocabulary valuable on a job site?','["It makes jobs take longer", "It hides information", "It sounds fancier", "It prevents misunderstandings that cause errors"]'::jsonb,3,'Accurate terms.','original'),
('127.922.d.3.A',3,'A trainee follows posted workplace rules about lockout of equipment and wears the required gear before servicing a conveyor. She is:','["consistently following workplace safety rules and regulations", "ignoring posted signs", "skipping lockout", "wearing no gear"]'::jsonb,0,'Safety rules.','original'),
('127.922.d.3.A',4,'Following safety rules is most important:','["only when it is convenient", "every time a task is performed", "only when watched", "only on the first day"]'::jsonb,1,'Always.','original'),
('127.922.d.3.B',3,'A trainee knows to stop work, tell her supervisor and fill out the incident form when a coworker is hurt by a loose pallet. She is:','["leaving without telling anyone", "hiding the injury", "demonstrating knowledge of procedures for reporting and handling accidents and safety incidents", "fixing the pallet first"]'::jsonb,2,'Reporting accidents.','original'),
('127.922.d.3.B',4,'Why must workers report every accident, even a small one?','["Only managers need to know", "Reports create more paperwork", "Small accidents never matter", "Reports help prevent the same accident from happening again"]'::jsonb,3,'Report it.','original'),
('127.922.d.4.A',3,'A trainee finishes each assigned task as directed, stays busy when work is slow and keeps a good attitude. She is:','["demonstrating a positive, productive work ethic by performing assigned tasks as directed", "doing the minimum", "avoiding tasks", "waiting to be told twice"]'::jsonb,0,'Work ethic.','original'),
('127.922.d.4.A',4,'A supervisor is away for the afternoon and a junior worker still stacks every pallet and cleans the bay. What does this show?','["A habit of cutting corners", "A strong, self-driven work ethic", "A wish to avoid coworkers", "A need for constant supervision"]'::jsonb,1,'Dependable effort without oversight.','original'),
('127.922.d.4.B',3,'A coworker asks a trainee to round up the hours on a shared log sheet, and she declines after considering what is fair and honest. She is:','["hiding the request", "guessing", "applying ethical reasoning to make an ethical decision", "agreeing to avoid conflict"]'::jsonb,2,'Ethical reasoning.','original'),
('127.922.d.4.B',4,'An ethical decision at work is one that is:','["quick and easy", "profitable for one person", "kept secret", "honest and fair to everyone affected"]'::jsonb,3,'Fair and honest.','original'),
('127.922.d.4.C',3,'A trainee checks that her driving hours and her paperwork follow all the laws and company rules before a trip. She is:','["complying with all applicable rules, laws and regulations in a consistent manner", "bending rules", "doing it only sometimes", "skipping paperwork"]'::jsonb,0,'Compliance.','original'),
('127.922.d.4.C',4,'Why do transportation workers have to follow laws and regulations?','["They are optional", "They protect the safety of workers and the public", "They slow every job down", "They only apply to managers"]'::jsonb,1,'Regulations.','original'),
('127.922.d.5.A',3,'A trainee in a supervised practicum carries out a service task, writes up what she did and reviews how it went with her mentor. She is:','["working unsupervised", "skipping the write-up", "conducting, documenting and evaluating learning activities in a supervised transportation setting", "avoiding review"]'::jsonb,2,'Supervised learning.','original'),
('127.922.d.5.A',4,'Documenting a learning activity helps a student because it:','["adds no value", "replaces practice", "hides mistakes", "creates a record she can review and improve from"]'::jsonb,3,'Documentation.','original'),
('127.922.d.5.B',3,'A trainee practices a new brake inspection method under supervision to move beyond basic skills for her chosen occupation. She is:','["developing advanced technical knowledge and skills related to her occupational objective", "avoiding practice", "changing careers", "staying at the basics"]'::jsonb,0,'Advanced knowledge.','original'),
('127.922.d.5.B',4,'Advanced skills in an occupation are usually built by:','["avoiding supervision", "repeated practice with feedback from experts", "one short lesson", "reading one page"]'::jsonb,1,'Practice and feedback.','original'),
('127.922.d.5.C',3,'A trainee''s logbook shows she now completes a tire service in half the time with fewer errors than in the fall. She is:','["staying the same", "losing skills", "demonstrating growth of technical skill competencies", "hiding records"]'::jsonb,2,'Growth.','original'),
('127.922.d.5.C',4,'A good way to show skill growth over time is to:','["compare to nothing", "ignore the records", "count only mistakes", "compare earlier and later results"]'::jsonb,3,'Compare.','original'),
('127.922.d.5.D',3,'A trainee reviews her checklist and notes that she is strong at inspections but needs practice on documentation. She is:','["evaluating strengths and weaknesses in technical skill proficiency", "hiding weaknesses", "guessing", "ignoring her results"]'::jsonb,0,'Self-evaluation.','original'),
('127.922.d.5.D',4,'Knowing a weakness in a skill allows a student to:','["stop learning", "plan practice where it is needed most", "hide it", "avoid the skill"]'::jsonb,1,'Target practice.','original'),
('127.922.d.5.E',3,'A trainee saves a photo of a finished repair, a completed inspection form and a supervisor''s note in a folder. She is:','["throwing away records", "avoiding documentation", "collecting representative work samples", "saving random items"]'::jsonb,2,'Work samples.','original'),
('127.922.d.5.E',4,'A representative work sample should:','["be the worst example", "be someone else''s work", "be unrelated", "show typical, quality work from the student"]'::jsonb,3,'Representative.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
